def _default_val_shards() -> list[dict]:  
    return json.loads(os.environ["GYM_VAL_SHARDS"])


def _default_val_batch_size() -> int:  
    shards = json.loads(os.environ["GYM_VAL_SHARDS"])
    return max(int(shard["val_batch_size"]) for shard in shards) if shards else 1


