# Patch all three build scripts: CJK chars -> 2-char bigram units (effective 16-char n-grams)
import re
patch_old = '''WORD_RE = re.compile(r"[a-z0-9']+|[\\u3400-\\u9fff\\u3040-\\u30ff\\uac00-\\ud7af]")

def norm_words(s):
    return WORD_RE.findall(s.lower())'''
patch_new = '''WORD_RE = re.compile(r"[a-z0-9']+|[\\u3400-\\u9fff\\u3040-\\u30ff\\uac00-\\ud7af]")

def norm_words(s):
    """ASCII words as tokens; CJK chars chunked into 2-char units (NG=8 -> 16-char match)."""
    out = []
    run = []
    for m in WORD_RE.finditer(s.lower()):
        t = m.group(0)
        if len(t) == 1 and ord(t[0]) > 0x3000:
            run.append(t)
        else:
            if run:
                out.extend(run[i:i+2] for i in range(0, len(run), 2))
                run = []
            out.append(t)
    if run:
        out.extend(run[i:i+2] for i in range(0, len(run), 2))
    return out'''
for f in ['build_v2.py', 'build_v2b.py', 'build_v2c.py']:
    src = open(f).read()
    if patch_old in src:
        src = src.replace(patch_old, patch_new)
        open(f, 'w').write(src)
        print(f, 'patched')
    else:
        print(f, 'PATTERN NOT FOUND')
